import{z as p,x as d,o as t,c as A,q as r,j as s,D as l,d as e,s as i,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"采样器内核","description":"","frontmatter":{"title":"采样器内核","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sampler-kernel.md","filePath":"llm/sampler-kernel.md","lastUpdated":1791413859000}'),m={name:"llm/sampler-kernel.md"};function B(c,a,h,f,T,C){const E=d("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="采样器内核" tabindex="-1">采样器内核 <a class="header-anchor" href="#采样器内核" aria-label="Permalink to &quot;采样器内核&quot;">​</a></h1><div class="epigraph"><p>逐步采样看起来像一次 softmax 加一次多项式抽签；在连续批里它是「每请求不同温度、不同核、不同 bias」的不规则核，处理不好就会比注意力还刺眼。</p><footer>—— 对照 vLLM / TensorRT-LLM / FlashInfer 把采样收进融合核的做法；分布定义见 Holtzman et al., ICLR 2020</footer></div><p><a href="/llm/streaming-detokenize">上一课</a>把字符串边界留在 CPU / 网关。本课回到 GPU：logits 已经在设备上，若 D2H 整份词表再在 Python 里采样，词表 10 万、batch 数百时，搬运与同步会吃掉 decode 步。采样器内核把温度、<a href="/llm/logit-bias">logit bias</a>、top-\\(k\\) / top-\\(p\\)、多项式抽样，以及可选的文法掩码，收成设备上的融合路径。后课才把文法本身的开销展开；这里先修「采样是热路径上的核，不是脚本」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一步 decode 的注意力与 MLP 可以融合；采样却常被写成：拷 logits → <code>softmax</code> → 主机上 <code>random.choice</code>。小 batch 时被掩盖；连续批把 batch 拉到容量墙附近后，词表维的带宽与核启动变成可见项。更麻烦的是 <em>每请求状态不同</em>：\\(T\\)、\\(p\\)、\\(k\\)、\\(b\\)、是否贪心、是否有掩码，不能打成一个整齐的 GEMM。缺口是：在不规则参数下仍把采样留在设备上，并与<a href="/llm/sampling-temperature-topp">温度协议</a>一致——包括 \\(T=0\\) 走 argmax，而不是极小温度加核。<span class="marginnote">数字感受一下：词表 12.8 万时一份 FP32 logits 约 0.5 MB；batch 256 意味着一步 decode 来回搬运约 128 MB。PCIe 往返要毫秒级，而留在设备上只需几微秒——这就是高并发下采样从「隐形」变「刺眼」的原因。</span></p><p>随机数质量与可复现性是第二缺口。设备 RNG 与主机 Python 不同；TP 下各 rank 的 logits 归约后再采，必须只在一处采，否则分叉。不要用种子当正确性测试，先修课已说；内核仍要保证 <em>同一 rank、同一算法</em> 的可重复，便于调试。</p><p><span class="marginnote">argmax 路径不应进入 softmax：半精度下指数会溢，且浪费。内核应分发：贪心一条，有限核一条，带掩码一条。过度模板化会膨胀二进制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>融合顺序与协议一致：掩码（置 <code>-inf</code>）→ 加 bias → 除以 \\(T\\) → 求 top-\\(k\\) 或扫描核（top-\\(p\\) 需要对排序或直方图）→ 归一化 → 按 CDF 抽样。top-\\(p\\) 的朴素实现是对词表排序，延迟随 \\(|\\mathcal{V}|\\) 变；生产核用 radix select、部分排序或近似核，必须在文档里声明是否与主机 <code>torch.multinomial</code> 比特一致——通常不一致，只要求分布在容差内。</p><p>连续批：每行一个参数结构体（\\(T,p,k\\) 指针到 bias 与 mask）。实现应避免为最大词表物化稠密 mask；文法引擎提供稀疏合法集时，采样在合法集上做，而不是先写满 \\(|\\mathcal{V}|\\) 再乘。贪心请求与采样请求不要在同一次不规则核里硬挤到同一控制流而不做分派：贪心可以提前结束该行。</p>',10)),(t(),s(n,null,{default:l(()=>[i(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E8%AE%BE%E5%A4%87%E4%B8%8A%20logits%22%5D%20--%3E%20FUSE%5B%22%E6%8E%A9%E7%A0%81%20bias%20%E6%B8%A9%E5%BA%A6%22%5D%0A%20%20FUSE%20--%3E%20SEL%5B%22top-k%20%2F%20nucleus%20%E9%80%89%E6%8B%A9%22%5D%0A%20%20SEL%20--%3E%20RNG%5B%22%E8%AE%BE%E5%A4%87%20RNG%20%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20LOG%20--%3E%20BAD%5B%22D2H%20%E6%95%B4%E8%A1%A8%20%2B%20%E4%B8%BB%E6%9C%BA%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("decode 带宽墙上，多搬一次 \\(|\\mathcal{V}|\\) 的 logits 到主机，相当于额外一轮中等大小的向量 IO，且打断流水。留在设备上后，采样通常不是屋顶：相对读权重，词表向量仍小。例外是极大词表（十万以上）加每步排序的 top-\\(p\\)，这时采样核自己变成延迟项，需要更好的选择算法或关 top-\\(p\\) 改 min-\\(p\\) / 贪心。与"),o("a",{href:"/llm/speculative-decoding"},"投机"),e("结合时，校验步要对 \\(\\gamma\\) 个位置各采一次接受决策，采样核变成「短序列、多位置」，批形状又变。")],-1)),(t(),s(n,null,{default:l(()=>[i(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E8%BF%9E%E7%BB%AD%E6%89%B9%3A%20%E6%AF%8F%E8%A1%8C%E8%87%AA%E5%B8%A6%20T%2C%20p%2C%20k%2C%20bias%2C%20%E6%8E%A9%E7%A0%81%E6%8C%87%E9%92%88%22%5D%20--%3E%20D%7B%22%E6%8C%89%E8%A1%8C%E5%88%86%E6%B4%BE%22%7D%0A%20%20D%20--%20%22T%20%3D%200%2C%20%E8%B4%AA%E5%BF%83%22%20--%3E%20A%5B%22argmax%2C%20%E8%AF%A5%E8%A1%8C%E6%8F%90%E5%89%8D%E6%94%B6%E5%B7%A5%22%5D%0A%20%20D%20--%20%22%E6%9C%89%E9%99%90%E6%A0%B8%20top-k%20%2F%20top-p%22%20--%3E%20S%5B%22%E9%80%89%E6%8B%A9%E5%90%8E%E5%9C%A8%E8%AE%BE%E5%A4%87%E4%B8%8A%E6%8C%89%20CDF%20%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20D%20--%20%22%E5%B8%A6%E6%96%87%E6%B3%95%E6%8E%A9%E7%A0%81%22%20--%3E%20M%5B%22%E5%9C%A8%E7%A8%80%E7%96%8F%E5%90%88%E6%B3%95%E9%9B%86%E4%B8%8A%E9%87%87%2C%20%E4%B8%8D%E7%89%A9%E5%8C%96%E6%95%B4%E8%A1%A8%22%5D%0A%20%20A%20--%3E%20OUT%5B%22%E5%90%8C%E4%B8%80%E5%86%85%E6%A0%B8%E5%87%BA%E5%8F%A3%2C%20%E6%97%A0%E4%B8%BB%E6%9C%BA%E5%90%8C%E6%AD%A5%22%5D%0A%20%20S%20--%3E%20OUT%0A%20%20M%20--%3E%20OUT%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">FlashInfer 一类库把采样与注意力同样当 kernel 目录里的条目。引擎若只融合注意力、采样走 PyTorch 算子碎片，profile 会在 <code>multinomial</code> 上冒出尖刺。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要为了「与 numpy 比特一致」在热路径保留主机采样。不要在 TP 的每个 rank 上独立采样。结构化输出的掩码生成若在主机，采样核再快也会等掩码——这是下一课的开销。数值：<code>-inf</code> 掩码在 FP16 要真的是 <code>-inf</code>，否则核里仍有质量泄漏。<span class="marginnote">常见误区：以为采样是「一小步数学」不值得优化。它本身运算量极少，但处在每步 decode 的必经路上——一次多余的设备到主机同步会打断整条流水线，成本按「同步次数 × 每次延迟」乘出来，而不是按 FLOPs 算。</span></p><p>出处：Holtzman et al. 定义核；工程实现以 vLLM、TensorRT-LLM、FlashInfer 的采样核为准。无单独必引的「采样器内核」会议论文，不编造。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>采样应留在设备上融合；D2H 整表在高并发 decode 上可见。</li><li>每请求 \\(T,p,k,b\\)、掩码不同，核是不规则的。</li><li>\\(T=0\\) 走 argmax；TP 只在一处采样。</li><li>top-\\(p\\) 的排序实现可能自己成为屋顶。</li><li>与投机、连续批的形状变化要单独测。</li><li>后课：掩码从哪来、要花多少钱。</li><li>出处：Holtzman et al., ICLR 2020；vLLM / TensorRT-LLM / FlashInfer 采样实现。</li></ul>',6))])}const k=p(m,[["render",B]]);export{u as __pageData,k as default};
